/**
 * Unit tests for DOMNodePointer.getLocalName
 */
public class DOMNodePointer_getLocalName_TriageGen2Test {

    @Test
    public void testGetLocalName_WithValidLocalName() {
        Node node = mock(Node.class);
        when(node.getLocalName()).thenReturn("myLocalName");

        String result = DOMNodePointer.getLocalName(node);

        assertEquals("myLocalName", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndNoColonInNodeName() {
        Node node = mock(Node.class);
        when(node.getLocalName()).thenReturn(null);
        when(node.getNodeName()).thenReturn("simpleName");

        String result = DOMNodePointer.getLocalName(node);

        assertEquals("simpleName", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndColonInNodeName() {
        Node node = mock(Node.class);
        when(node.getLocalName()).thenReturn(null);
        when(node.getNodeName()).thenReturn("prefix:localName");

        String result = DOMNodePointer.getLocalName(node);

        assertEquals("localName", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndTrailingColon() {
        Node node = mock(Node.class);
        when(node.getLocalName()).thenReturn(null);
        when(node.getNodeName()).thenReturn("prefix:");

        String result = DOMNodePointer.getLocalName(node);

        assertEquals("", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndLeadingColon() {
        Node node = mock(Node.class);
        when(node.getLocalName()).thenReturn(null);
        when(node.getNodeName()).thenReturn(":justColon");

        String result = DOMNodePointer.getLocalName(node);

        assertEquals("justColon", result);
    }

    @Test
    public void testGetLocalName_WithNullLocalNameAndMultipleColons() {
        Node node = mock(Node.class);
        when(node.getLocalName()).thenReturn(null);
        // The code uses lastIndexOf(':'), so it should take everything after the last colon
        when(node.getNodeName()).thenReturn("a:b:c");

        String result = DOMNodePointer.getLocalName(node);

        assertEquals("c", result);
    }
}
